select lang.id, 'Test type TOEIC-like — Niveau 2', '{"duration_minutes": 45, "part_a": [{"question": "Complète : My sister ___ in London for five years.", "options": ["lives", "has lived", "lived", "living"], "correct_index": 1}, {"question": "Complète : By the time we arrived, the show ___ already started.", "options": ["has", "had", "have", "was"], "correct_index": 1}, {"question": "Complète : If I ___ more time, I would learn Japanese.", "options": ["have", "had", "will have", "has"], "correct_index": 1}, {"question": "Complète : The bridge ___ in 1932.", "options": ["build", "built", "was built", "is built"], "correct_index": 2}, {"question": "Complète : She asked me where ___.", "options": ["I lived", "did I live", "I live", "lived I"], "correct_index": 0}, {"question": "Complète : ___ you finished your homework yet?", "options": ["Do", "Did", "Have", "Are"], "correct_index": 2}, {"question": "Complète : This is the man ___ car was stolen.", "options": ["who", "whose", "which", "that"], "correct_index": 1}, {"question": "Complète : I''m looking forward ___ you.", "options": ["to see", "seeing", "to seeing", "see"], "correct_index": 2}, {"question": "Complète : He denied ___ the vase.", "options": ["break", "to break", "breaking", "broke"], "correct_index": 2}, {"question": "Complète : ___ had I left when it started raining.", "options": ["No sooner", "Hardly", "Never", "Rarely"], "correct_index": 1}, {"question": "Complète : The report ___ by tomorrow.", "options": ["must finish", "must be finished", "must finished", "must being finished"], "correct_index": 1}, {"question": "Complète : I wish I ___ more languages.", "options": ["speak", "spoke", "had spoken", "will speak"], "correct_index": 1}, {"question": "Complète : She''s the person ___ helped us yesterday.", "options": ["who", "whom", "whose", "which"], "correct_index": 0}, {"question": "Complète : They ___ dinner when the phone rang.", "options": ["had", "have had", "were having", "has"], "correct_index": 2}, {"question": "Complète : It''s important that everyone ___ on time.", "options": ["arrive", "arrives", "arrived", "will arrive"], "correct_index": 0}, {"question": "Complète : We ___ finish this project by Friday.", "options": ["have to", "must to", "should to", "can to"], "correct_index": 0}, {"question": "Complète : This restaurant is ___ than the one we tried last week.", "options": ["good", "better", "best", "more good"], "correct_index": 1}, {"question": "Complète : ___ despite the heavy rain, the match continued.", "options": ["Although", "Because", "Despite", "So"], "correct_index": 2}, {"question": "Complète : He must ___ the email already; he hasn''t replied.", "options": ["not receive", "not have received", "not received", "not receiving"], "correct_index": 1}, {"question": "Complète : What ___ is a bit more time to think it over.", "options": ["I need", "do I need", "I am needing", "needed I"], "correct_index": 0}, {"question": "Complète : She''s used to ___ up early.", "options": ["wake", "waking", "woke", "to wake"], "correct_index": 1}, {"question": "Complète : The meeting has been ___ until next week.", "options": ["postponed", "postpone", "postponing", "postpones"], "correct_index": 0}, {"question": "Complète : Neither of the candidates ___ suitable for the role.", "options": ["are", "is", "were", "have been"], "correct_index": 1}, {"question": "Complète : I''d rather you ___ smoke in the house.", "options": ["don''t", "didn''t", "won''t", "not"], "correct_index": 1}, {"question": "Complète : The company''s profits ___ significantly this quarter.", "options": ["rose", "raised", "have risen", "rise"], "correct_index": 2}, {"question": "Complète : It''s the way she talks to clients ___ impresses everyone.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : He''s the kind of manager who always ___ things done.", "options": ["get", "gets", "getting", "got"], "correct_index": 1}, {"question": "Complète : ___ working late, she finished the report on time.", "options": ["Despite", "Although", "In spite", "Because"], "correct_index": 0}, {"question": "Complète : I can''t find my glasses. I ___ left them at the office.", "options": ["should have", "must have", "would have", "can have"], "correct_index": 1}, {"question": "Complète : The negotiations fell ___ at the last minute.", "options": ["through", "out", "up", "down"], "correct_index": 0}], "part_b": [{"title": "Annonce interne", "passage": "Notice to all staff: The office kitchen will be closed for renovation from Monday to Wednesday next week. Please use the break room on the second floor during this period. We apologize for any inconvenience and thank you for your understanding.", "questions": [{"question": "What will be closed?", "options": ["The break room", "The office kitchen", "The second floor", "The office entrance"], "correct_index": 1}, {"question": "For how long will it be closed?", "options": ["One day", "Three days", "One week", "Two weeks"], "correct_index": 1}, {"question": "What should staff use instead?", "options": ["A nearby café", "The break room on the second floor", "Their own desks", "Nothing is provided"], "correct_index": 1}, {"question": "Why is the kitchen closed?", "options": ["Renovation", "Cleaning", "A staff event", "Not specified clearly, but implied maintenance"], "correct_index": 0}, {"question": "Who is this notice addressed to?", "options": ["Clients", "All staff", "Management only", "Visitors"], "correct_index": 1}, {"question": "What tone does the notice have?", "options": ["Angry", "Apologetic and polite", "Indifferent", "Urgent and alarming"], "correct_index": 1}]}, {"title": "Avis client (hôtel)", "passage": "We stayed at this hotel for three nights during our anniversary trip. The room was spacious and the view was stunning. Check-in was smooth, though we had to wait a bit for our room to be ready. The only downside was the noise from the street at night. Overall, we would recommend it for a short stay.", "questions": [{"question": "What was the occasion for the trip?", "options": ["A business trip", "An anniversary", "A conference", "A family reunion"], "correct_index": 1}, {"question": "How many nights did they stay?", "options": ["Two", "Three", "Four", "A week"], "correct_index": 1}, {"question": "What did they like about the room?", "options": ["The price", "The spaciousness and view", "The furniture", "The bathroom"], "correct_index": 1}, {"question": "What was the problem during check-in?", "options": ["Lost luggage", "A wait for the room", "Wrong room given", "No problem at all"], "correct_index": 1}, {"question": "What was the main complaint?", "options": ["Bad service", "Street noise at night", "Dirty room", "High price"], "correct_index": 1}, {"question": "Would the reviewer recommend it?", "options": ["No, never", "Yes, for a short stay", "Yes, for long stays only", "Not mentioned"], "correct_index": 1}]}, {"title": "Article court (technologie)", "passage": "A growing number of companies are allowing employees to choose their own working hours, as long as core tasks are completed. Supporters say this boosts productivity and job satisfaction. Critics argue it can make teamwork more difficult, especially across different time zones.", "questions": [{"question": "What are more companies allowing?", "options": ["Remote work only", "Flexible working hours", "Longer holidays", "Four-day weeks"], "correct_index": 1}, {"question": "What do supporters say about this?", "options": ["It increases costs", "It boosts productivity and satisfaction", "It reduces quality", "It has no effect"], "correct_index": 1}, {"question": "What do critics argue?", "options": ["It''s too expensive", "It can complicate teamwork", "Employees don''t like it", "It''s illegal"], "correct_index": 1}, {"question": "What condition is mentioned for flexible hours?", "options": ["Manager approval each day", "Core tasks must be completed", "A minimum of 40 hours", "None mentioned"], "correct_index": 1}, {"question": "What specific challenge is mentioned for teams?", "options": ["Language barriers", "Different time zones", "Lack of trust", "Technology issues"], "correct_index": 1}, {"question": "What is the overall tone of the article?", "options": ["Strongly against the trend", "Balanced, presenting both views", "Purely promotional", "Purely critical"], "correct_index": 1}]}, {"title": "Email professionnel", "passage": "Dear Ms. Carter, Thank you for your interest in our services. Following our call yesterday, please find attached the proposal we discussed, including pricing and timeline. Let me know if you have any questions or would like to schedule a follow-up meeting. Best regards, Daniel Reyes.", "questions": [{"question": "What is attached to the email?", "options": ["An invoice", "A proposal with pricing and timeline", "A contract to sign", "A product sample"], "correct_index": 1}, {"question": "When did the call take place?", "options": ["Today", "Yesterday", "Last week", "Not mentioned"], "correct_index": 1}, {"question": "What does Daniel offer to do?", "options": ["Cancel the deal", "Schedule a follow-up meeting", "Lower the price immediately", "End the conversation"], "correct_index": 1}, {"question": "Who is the email addressed to?", "options": ["Daniel Reyes", "Ms. Carter", "A team", "A supplier"], "correct_index": 1}, {"question": "What is the tone of the email?", "options": ["Informal and casual", "Professional and courteous", "Urgent and demanding", "Apologetic"], "correct_index": 1}, {"question": "What happened before this email was sent?", "options": ["A meeting in person", "A phone call", "A previous email", "Nothing, this is the first contact"], "correct_index": 1}]}, {"title": "Instructions (application mobile)", "passage": "To update your profile picture: 1. Open the app and tap your avatar in the top corner. 2. Select ''Edit Profile.'' 3. Tap on the current picture and choose ''Upload New Photo.'' 4. Select a photo from your gallery or take a new one. 5. Confirm and save your changes.", "questions": [{"question": "What is the first step?", "options": ["Select Edit Profile", "Tap the avatar", "Upload a photo", "Save changes"], "correct_index": 1}, {"question": "Where is the avatar located?", "options": ["Bottom of the screen", "Top corner", "Settings menu", "Not specified"], "correct_index": 1}, {"question": "What are the two photo options?", "options": ["Gallery photo or new photo", "Only gallery photos", "Only new photos", "Stock images"], "correct_index": 0}, {"question": "What is the last step?", "options": ["Tap the avatar", "Confirm and save", "Select Edit Profile", "Choose a filter"], "correct_index": 1}, {"question": "How many steps are there in total?", "options": ["Three", "Four", "Five", "Six"], "correct_index": 2}, {"question": "What must you tap to start editing?", "options": ["Settings icon", "Your avatar", "Home button", "Search bar"], "correct_index": 1}]}]}'::jsonb
from lang;
